'use strict';

/**
 * Generated by `aid infra gen`. Do not edit: the next run refuses to overwrite a
 * hand-edited file, and the construct carries no project-specific fact to keep.
 *
 * The AWS CDK spelling of `infra/generated/modules/alerts`: one CloudWatch alarm per
 * entry in `observability.alerts`. It reads `deploy.cdk-context.json`, so it cannot
 * disagree with the HCL module about which series is watched, over what window, or at
 * what threshold.
 *
 * Three things it deliberately does not do, matching the HCL module: it does not run the
 * OpenTelemetry Collector (it derives the namespace the collector has to publish into and
 * returns it), it does not choose a notification destination (`inputs.alertChannelArns`
 * belongs to the operator), and it does not treat missing data as healthy -- an alarm whose
 * series stopped arriving is not an alarm that came in under budget.
 */

const context = require('../deploy.cdk-context.json');

const WINDOW_SECONDS = {
  '5m': 300,
  '15m': 900,
  '1h': 3600,
  '6h': 21600,
  '24h': 86400,
};

/**
 * The CloudWatch statistic that applies the declared reduction.
 *
 * Kept identical to the HCL module's table: two backends that disagreed here would fire
 * on different quantities from the same document. Percentiles are not "statistic" values
 * on CloudWatch, so they travel in "extendedStatistic" instead.
 */
const STATISTICS = {
  sum: 'Sum',
  average: 'Average',
  max: 'Maximum',
};

/** CloudWatch spells percentiles as "pNN", and only in the extended-statistics argument. */
const EXTENDED_STATISTICS = {
  p95: 'p95',
};

/** The sentence a human reads in the console when the alarm fires. */
function description(alert) {
  const scope =
    alert.source === undefined ? 'across the whole environment' : 'for "' + alert.source + '"';
  return (
    alert.metric +
    ' (' +
    alert.aggregate +
    ') over ' +
    alert.window +
    ' exceeded ' +
    alert.threshold +
    ' ' +
    alert.unit +
    ' ' +
    scope +
    '. Declared in observability.alerts.'
  );
}

/**
 * Add one CloudWatch alarm per declared alert to a stack.
 *
 * @param {{ scope: import('aws-cdk-lib').Stack, inputs?: { alertChannelArns?: string[] } }} args
 * @returns {{ metricNamespace: string, alarmArns: string[] } | undefined} undefined when
 *   the document declared no alert
 */
function addAlerts(args) {
  const alerts = context.alerts;
  if (!alerts || alerts.length === 0) return undefined;

  const cloudwatch = require('aws-cdk-lib/aws-cloudwatch');

  const stack = args.scope;
  const inputs = args.inputs || {};
  const metricNamespace = 'AID/' + context.project.namespace + '/' + context.project.name;

  const alarmArns = alerts.map(function (alert) {
    const logicalId =
      'AidAlarm' +
      alert.id
        .split('_')
        .map(function (part) {
          return part.charAt(0).toUpperCase() + part.slice(1);
        })
        .join('');

    const alarm = new cloudwatch.CfnAlarm(stack, logicalId, {
      alarmName: 'aid-' + context.project.namespace + '-' + context.project.name + '-' + alert.id,
      alarmDescription: description(alert),
      namespace: metricNamespace,
      metricName: alert.metric,
      dimensions: alert.source === undefined ? undefined : [{ name: 'Source', value: alert.source }],
      period: WINDOW_SECONDS[alert.window],
      statistic: STATISTICS[alert.aggregate],
      extendedStatistic: EXTENDED_STATISTICS[alert.aggregate],
      comparisonOperator: 'GreaterThanThreshold',
      threshold: alert.threshold,
      // One period is one evaluation: the window in the document is the period, so a
      // second evaluation would watch a longer span than the author declared.
      evaluationPeriods: 1,
      datapointsToAlarm: 1,
      treatMissingData: 'missing',
      alarmActions: inputs.alertChannelArns,
    });
    return alarm.attrArn;
  });

  return { metricNamespace: metricNamespace, alarmArns: alarmArns };
}

module.exports = { addAlerts: addAlerts };
